package com.qalsmartkeyboard.ime.emoji

import java.io.ByteArrayInputStream
import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/** The bundled assets (generated by `android/ime/scripts/build_emoji_data.py`) and their parser. */
class EmojiDataTest {
    companion object {
        /** The real bundled assets (unit tests run in the module directory). */
        val assets = EmojiSource { name -> File("src/main/assets/emoji/$name").takeIf { it.isFile }?.inputStream() }

        val catalog: EmojiCatalog by lazy { EmojiLoader(assets).load() }

        fun source(vararg files: Pair<String, String>): EmojiSource {
            val map = files.toMap()
            return EmojiSource { name -> map[name]?.let { ByteArrayInputStream(it.toByteArray(Charsets.UTF_8)) } }
        }
    }

    @Test fun everyCategoryHasEmoji() {
        for (c in EmojiCategory.entries) {
            if (c == EmojiCategory.RECENT) continue
            assertTrue("$c is empty", catalog.inCategory(c).isNotEmpty())
        }
        assertTrue(catalog.entries.size > 1500)
    }

    @Test fun categoriesFollowUnicodeGroups() {
        assertEquals(EmojiCategory.SMILEYS, catalog.entryFor("😀")!!.category) // grinning face
        assertEquals(EmojiCategory.FLAGS, catalog.entryFor("🇪🇹")!!.category) // Ethiopia
        assertEquals(EmojiCategory.FOOD, catalog.entryFor("🍔")!!.category) // hamburger
    }

    @Test fun zwjSequencesAreOneEntryAndFlagsAreTwoRegionalIndicators() {
        val family = "👨‍👩‍👧" // man, woman, girl
        assertNotNull(catalog.entryFor(family))
        val flag = catalog.entryFor("🇪🇹")!!
        assertEquals(4, flag.text.length)
        assertTrue(flag.name.contains("Ethiopia"))
    }

    @Test fun skinTonesAreGroupedUnderTheBaseEmoji() {
        val wave = catalog.entryFor("👋")!! // waving hand
        assertEquals(5, wave.variants.size)
        assertTrue(wave.hasTones)
        for (v in wave.variants) assertEquals(wave, catalog.entryFor(v))
        // A variant is never an entry of its own: the whole data set has no bare tone-modified base entries.
        assertTrue(catalog.entries.none { e -> e.text.codePoints().anyMatch { it in 0x1F3FB..0x1F3FF } })
        // A sequence without tone variants has none.
        assertFalse(catalog.entryFor("😀")!!.hasTones)
    }

    @Test fun onlyFullyQualifiedEmojiAreKept() {
        // Heart: the fully-qualified form carries the emoji presentation selector; the bare U+2764 is not an entry.
        assertNotNull(catalog.entryFor("❤️"))
        assertNull(catalog.entryFor("❤"))
        // The Component group (bare tone swatches) is not shown.
        assertNull(catalog.entryFor("🏻"))
    }

    @Test fun keycapEmojiStartingWithAHashAreNotTakenForComments() {
        assertNotNull(catalog.entryFor("#" + "️" + "⃣"))
        assertNotNull(catalog.entryFor("*" + "️" + "⃣"))
    }

    @Test fun keywordsAndNamesAreLoaded() {
        val grin = catalog.entryFor("😀")!!
        assertEquals("grinning face", grin.name)
        assertTrue("grin" in grin.keywords)
    }

    @Test fun annotationFilesLineUpWithTheEntries() {
        val total = assets.open("emoji.tsv")!!.bufferedReader().readLines().count { it.isNotEmpty() && !it.startsWith("# ") && it[0] != '@' }
        for (lang in listOf("am", "ti", "om")) {
            val a = EmojiLoader(assets).loadLanguage(lang)!!
            assertEquals("$lang entries", total, a.names.size)
        }
        val am = EmojiLoader(assets).loadLanguage("am")!!
        val grin = catalog.entryFor("😀")!!
        assertEquals("ፈገግ ያለ ፊት", am.names[grin.index])
        assertNull(EmojiLoader(assets).loadLanguage("xx"))
    }

    @Test fun unsupportedGlyphsAreFilteredAndTheAnswerIsCached() {
        var asked = 0
        val saved = HashSet<String>()
        var cached: Set<String>? = null
        val cache = object : GlyphCache {
            override fun load() = cached
            override fun save(unsupported: Set<String>) { cached = unsupported; saved += unsupported }
        }
        val src = source("emoji.tsv" to "@Smileys & Emotion\n😀\tgrinning face\tgrin\t\n🫠\tmelting face\t\t\n")
        val first = EmojiLoader(src, { asked++; it != "🫠" }, cache).load()
        assertEquals(listOf("😀"), first.entries.map { it.text })
        assertEquals(2, asked)
        // Second load: the cached answer is used, no glyph is checked again.
        val second = EmojiLoader(src, { asked++; true }, cache).load()
        assertEquals(2, asked)
        assertEquals(listOf("😀"), second.entries.map { it.text })
    }

    @Test fun fileGlyphCacheRoundTripsAndInvalidatesOnAnotherBuild() {
        val f = File.createTempFile("glyphs", ".txt")
        try {
            FileGlyphCache(f, "build-1").save(setOf("a", "b"))
            assertEquals(setOf("a", "b"), FileGlyphCache(f, "build-1").load())
            assertNull(FileGlyphCache(f, "build-2").load())
        } finally {
            f.delete()
        }
    }

    @Test fun assetsStayCompact() {
        val dir = File("src/main/assets/emoji")
        // What is loaded for one language: the English data plus that language's annotations.
        for (lang in listOf("am", "ti", "om")) {
            val bytes = File(dir, "emoji.tsv").length() + File(dir, "emoji-$lang.tsv").length()
            assertTrue("$lang loads $bytes bytes", bytes < 400_000)
        }
        assertTrue(File(dir, "UNICODE-LICENSE.txt").isFile)
    }
}
